WITH problems AS (SELECT 'Thiếu hàm xóa mềm mã hàng' AS problem WHERE to_regprocedure('public.admin_soft_delete_products_v1(uuid[])') IS NULL UNION ALL SELECT 'Thiếu hàng rào giữ lịch sử mã hàng' WHERE to_regprocedure('public.products_guard_deletion_v1()') IS NULL UNION ALL SELECT 'Thiếu trigger bảo vệ mã hàng' WHERE NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.products'::regclass AND tgname='trg_products_guard_deletion_v1' AND tgenabled='O' AND NOT tgisinternal AND tgfoid=to_regprocedure('public.products_guard_deletion_v1()')) UNION ALL SELECT 'Sai quyền gọi hàm xóa mã hàng' WHERE EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='admin_soft_delete_products_v1' AND (NOT p.prosecdef OR NOT has_function_privilege('authenticated',p.oid,'EXECUTE') OR has_function_privilege('anon',p.oid,'EXECUTE'))) UNION ALL SELECT 'Hàm xóa mã hàng mở quyền PUBLIC' WHERE EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='public' AND p.proname IN('admin_soft_delete_products_v1','products_guard_deletion_v1') AND a.grantee=0 AND a.privilege_type='EXECUTE')) SELECT problem FROM problems;
